{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-8e77b61d677ed59a","type":"tool_result","content":"1\t\"\"\"Phase-aware progress checker for agent polling.\n2\t\n3\tReports completion status for a list of strategy IDs based on the current phase.\n4\tSupports ``--wait`` mode which sleeps internally so the caller does not need\n5\tto parse ``NEXT_POLL`` values.\n6\t\"\"\"\n7\t\n8\timport argparse\n9\timport os\n10\timport sys\n11\timport time\n12\t\n13\timport yaml\n14\t\n15\tsys.path.insert(0, os.path.dirname(__file__))\n16\tfrom artifact_utils import read_frontmatter\n17\t\n18\t\n19\tPHASE_CHECKS = {\n20\t    \"fetch\": lambda id: f\"artifacts/strat-tasks/{id}.md\",\n21\t    \"decompose\": lambda id: f\"artifacts/epic-tasks/{id}-decomposition.md\",\n22\t    \"review_decomp\": lambda id: f\"artifacts/epic-reviews/{id}-decomp-review.md\",\n23\t    \"revise_decomp\": lambda id: f\"artifacts/epic-tasks/{id}-decomposition.md\",\n24\t}\n25\t\n26\t\n27\t\n28\tdef _decompose_complete(strat_id, data):\n29\t    \"\"\"Whether the decompose agent has finished writing for this strategy.\n30\t\n31\t    The agent sets ``decompose_complete`` as its final action (Step 8c), so\n32\t    that field is authoritative.  When the field is absent (agent died or\n33\t    older prompt), returns False — the pipeline's --max-wait timeout will\n34\t    report the strategy as stuck rather than silently proceeding with\n35\t    incomplete output.\n36\t    \"\"\"\n37\t    return bool(data.get(\"decompose_complete\"))\n38\t\n39\t\n40\tdef check_id(phase, strat_id):\n41\t    \"\"\"Check one ID. Returns 'completed', 'pending', or 'error'.\"\"\"\n42\t    path = PHASE_CHECKS[phase](strat_id)\n43\t    if not os.path.exists(path):\n44\t        return \"pending\"\n45\t    if phase == \"decompose\":\n46\t        try:\n47\t            data, _ = read_frontmatter(path)\n48\t        except Exception:\n49\t            return \"pending\"\n50\t        if not data:\n51\t            r