{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-be465fe1d1dc9f9b","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"CLI for reading, writing, and inspecting artifact frontmatter.\n3\t\n4\tSkills call this script instead of writing YAML by hand, ensuring\n5\tschema-validated frontmatter on all artifact files.\n6\t\n7\tUsage:\n8\t    # Show schema for a file type\n9\t    python3 scripts/frontmatter.py schema strat-task\n10\t    python3 scripts/frontmatter.py schema epic-task\n11\t    python3 scripts/frontmatter.py schema decomp-summary\n12\t    python3 scripts/frontmatter.py schema decomp-review\n13\t\n14\t    # Set/update frontmatter on a file (validates before writing)\n15\t    python3 scripts/frontmatter.py set artifacts/epic-tasks/RHAISTRAT-1234-E001.md \\\n16\t        epic_id=RHAISTRAT-1234-E001 parent_strat=RHAISTRAT-1234 \\\n17\t        component=model-serving team=model-serving type=Implementation \\\n18\t        priority=P0 ai_implementability=High ai_implementability_score=5\n19\t\n20\t    # Set nested fields with dot notation\n21\t    python3 scripts/frontmatter.py set artifacts/epic-tasks/RHAISTRAT-1234-E001.md \\\n22\t        gate_failure_impact.action=rewrite \\\n23\t        gate_failure_impact.fallback_approach=\"Use alternative approach\"\n24\t\n25\t    # Read and validate frontmatter from a file\n26\t    python3 scripts/frontmatter.py read artifacts/epic-tasks/RHAISTRAT-1234-E001.md\n27\t\n28\t    # Read frontmatter from multiple files\n29\t    python3 scripts/frontmatter.py batch-read artifacts/epic-tasks/*.md\n30\t\"\"\"\n31\t\n32\timport argparse\n33\timport json\n34\timport os\n35\timport sys\n36\t\n37\tfrom artifact_utils import (\n38\t    SCHEMAS,\n39\t    get_schema_yaml,\n40\t    read_frontmatter,\n41\t    read_frontmatter_validated,\n42\t    write_frontmatter,\n43\t    update_frontmatter,\n44\t    ValidationError,\n45\t)\n46\t\n47\t\n48\tdef _coerce_value(value_str, field_spec):\n49\t    \"\"