ation -> routing model; everything\n102\t    # else -> Implementation signal sum.\n103\t    if data.get(\"type\") == \"Investigation\":\n104\t        inv = data.get(\"investigation_signals\")\n105\t        if not isinstance(inv, dict):\n106\t            return None\n107\t        total, classification = classify_investigation(inv)\n108\t    else:\n109\t        signals = data.get(\"ai_signals\")\n110\t        if not signals or not isinstance(signals, dict):\n111\t            return None\n112\t\n113\t        total = 0\n114\t        for field in SIGNAL_FIELDS:\n115\t            val = signals.get(field, 0)\n116\t            if val is None:\n117\t                val = 0\n118\t            total += val\n119\t\n120\t        classification = classify(total)\n121\t\n122\t    epic_id = data.get(\"epic_id\", os.path.basename(epic_path))\n123\t\n124\t    old_score = data.get(\"ai_implementability_score\")\n125\t    old_class = data.get(\"ai_implementability\")\n126\t\n127\t    if old_score != total or old_class != classification:\n128\t        update_frontmatter(epic_path, {\n129\t            \"ai_implementability_score\": total,\n130\t            \"ai_implementability\": classification,\n131\t        }, \"epic-task\")\n132\t        changed = \" (updated)\"\n133\t    else:\n134\t        changed = \"\"\n135\t\n136\t    return epic_id, total, classification, changed\n137\t\n138\t\n139\tdef compute_for_strategy(strat_id):\n140\t    \"\"\"Compute scores for all epics of a strategy. Returns count of epics processed.\"\"\"\n141\t    # Two explicit patterns: conditional decompositions name their epics\n142\t    # {strat_id}-BRANCH-<X>-E00N.md, which {strat_id}-E*.md cannot match — the\n143\t    # 2026-08-19 eval's case-007 shipped 7 of 8 epics unscored because of it.\n144\t    # (Not {strat_id}*-E*.md: that would cross-match longer strategy ids\n145\t    # sharing the prefix.)\n146\t    epic_files = sorted(\n147\t        glob.glob(f\"artifacts/epic-tasks/{strat_id}-E*.md\")\n148\t      