rrent UTC timestamp in ISO 8601 format.\"\"\"\n    from datetime import datetime, timezone\n    print(datetime.now(timezone.utc).strftime(\"%Y-%m-%dT%H:%M:%SZ\"))\n\n\ndef _parse_pairs(args):\n    \"\"\"Parse key=value arguments into (key, value) tuples.\"\"\"\n    pairs = []\n    for arg in args:\n        if \"=\" not in arg:\n            print(f\"Invalid key=value: {arg}\", file=sys.stderr)\n            sys.exit(1)\n        k, v = arg.split(\"=\", 1)\n        pairs.append((k, v))\n    return pairs\n\n\nCOMMANDS = {\n    \"init\": cmd_init,\n    \"set\": cmd_set,\n    \"set-default\": cmd_set_default,\n    \"read\": cmd_read,\n    \"write-ids\": cmd_write_ids,\n    \"read-ids\": cmd_read_ids,\n    \"timestamp\": cmd_timestamp,\n}\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:\n        print(f\"Commands: {', '.join(COMMANDS)}\", file=sys.stderr)\n        sys.exit(1)\n    COMMANDS[sys.argv[1]](sys.argv[2:])\n","numLines":174,"startLine":1,"totalLines":174}},"tool_result_meta":[{"id":"chatcmpl-tool-ad50dba6611c044b","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
