              entry[\"status\"] = \"passed\"\n53\t                entry[\"score\"] = data.get(\"score\")\n54\t            else:\n55\t                entry[\"status\"] = \"failed\"\n56\t                entry[\"score\"] = data.get(\"score\")\n57\t\n58\t        results.append(entry)\n59\t\n60\t    report = {\n61\t        \"started\": opts.start_time,\n62\t        \"completed\": end_time,\n63\t        \"batch_size\": opts.batch_size,\n64\t        \"total\": len(ids),\n65\t        \"results\": results,\n66\t    }\n67\t\n68\t    os.makedirs(\"artifacts/decompose-runs\", exist_ok=True)\n69\t    ts = opts.start_time.replace(\":\", \"-\")\n70\t    report_path = f\"artifacts/decompose-runs/{ts}.yaml\"\n71\t    with open(report_path, \"w\") as f:\n72\t        yaml.dump(report, f, default_flow_style=False, sort_keys=False)\n73\t\n74\t    print(f\"Report written to {report_path}\")\n75\t\n76\t\n77\tif __name__ == \"__main__\":\n78\t    main()\n79\t"}]},"parent_tool_use_id":null,"session_id":"7da9b899-2570-4f45-9105-189f12061fa7","uuid":"26c4c729-0d74-4a4c-a9b5-46208bacc005","timestamp":"2026-10-09T12:26:01.819Z","tool_use_result":{"type":"text","file":{"filePath":"/private/var/folders/h5/l8qslbp55w5621qf9ngsh5jc0000gn/T/epic_case-016-component-canonicalization_0_0uz2244h/scripts/generate_run_report.py","content":"#!/usr/bin/env python3\n\"\"\"Generate run report for a decomposition pipeline run.\"\"\"\n\nimport argparse\nimport os\nimport sys\nfrom datetime import datetime, timezone\n\nimport yaml\n\nsys.path.insert(0, os.path.dirname(__file__))\nfrom artifact_utils import read_frontmatter\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--start-time\", required=True)\n    parser.add_argument(\"--batch-size\", type=int, default=25)\n    parser.add_argument(\"ids\", nargs=\"*\")\n    opts = parser.parse_args()\n\n    ids = opts.ids\n    if not ids:\n        ids_file = \"tmp/pipeline-all-ids.txt\"\n        if os.path.exists(ids_file):\n            with open(ids_file) as f:\n                ids = [line.strip() for line in f if line.strip()]\n\n    if not ids:\n        print(\"No IDs to report on\", file=sys.stderr)\n        sys.exit(1)\n\n    end_time = datetime.now(timezone.utc).strftime(\"%Y-%m-%dT%H:%M:%SZ\")\n\n    results = []\n    for strat_id in ids:\n        entry = {\"strat_id\": strat_id, \"status\": \"missing\"}\n        decomp = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n        review = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n\n        if os.path.exists(decomp):\n            data, _ = read_frontmatter(decomp)\n            entry[\"epic_count\"] = data.get(\"epic_count\", 0)\n            entry[\"status\"] = \"decomposed\"\n\n        if os.path.exists(review):\n            data, _ = read_frontmatter(review)\n            if data.get(\"error\"):\n                entry[\"status\"] = \"error\"\n                entry[\"error\"] = data[\"error\"]\n            elif data.get(\"pass\"):\n                entry[\"status\"] = \"passed\"\n                entry[\"score\"] = data.get(\"score\")\n            else:\n                entry[\"status\"] = \"failed\"\n                entry[\"score\"] = data.get(\"score\")\n\n        results.append(entry)\n\n    report = {\n        \"started\": opts.start_time,\n        \"completed\": end_time,\n        \"batch_size\": opts.batch_size,\n        \"total\": len(ids),\n        \"results\": results,\n    }\n\n    os.makedirs(\"artifacts/decompose-runs\", exist_ok=True)\n    ts = opts.start_time.replace(\":\", \"-\")\n    report_path = f\"artifacts/decompose-runs/{ts}.yaml\"\n    with open(report_path, \"w\") as f:\n        yaml.dump(report, f, default_flow_style=False, sort_keys=False)\n\n    print(f\"Report written to {report_path}\")\n\n\nif __name__ == \"__main__\":\n    main()\n","numLines":79,"startLine":1,"totalLines":79}},"tool_result_meta":[{"id":"chatcmpl-tool-a6464a6ea946da1e","permission_decision":{"decision":"accept","source":"config"