{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-9e9f5b7ea78ced20","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Structural consistency self-check for epic decompositions.\n3\t\n4\tUsage:\n5\t    python3 check_decomposition.py <STRATEGY_ID> [--epic-dir artifacts/epic-tasks]\n6\t    python3 check_decomposition.py --self-check\n7\t\n8\tChecks (structural invariants only — no semantic judgment, so a finding is\n9\talways a real inconsistency the downstream review rubric scores as critical):\n10\t\n11\t  mermaid-frontmatter   Every dependency edge in the decomposition summary's\n12\t                        Mermaid DAG has a matching entry in the dependent\n13\t                        epic's frontmatter `dependencies`, and every\n14\t                        frontmatter dependency of a main-plan epic appears as\n15\t                        an edge in the diagram (both directions).\n16\t  dangling-dependency   An epic's `dependencies` references an epic_id that\n17\t                        has no file on disk.\n18\t  main-plan-branch-dep  A main-plan epic lists a `-BRANCH-<letter>-` epic in\n19\t                        its `dependencies` (branch epics are never created as\n20\t                        issues; depending on one dangles).\n21\t  dependency-cycle      The frontmatter dependency graph has a cycle.\n22\t\n23\tEach finding names the file, the defect, and the exact fix. Exit 0 with\n24\t\"OK: ...\" when there are no findings; exit 1 with FINDING lines otherwise.\n25\tExit 2 on usage/parse trouble BEFORE any artifacts were read (callers treat\n26\tnon-zero-with-no-FINDING-lines as \"check unavailable\" and proceed).\n27\t\"\"\"\n28\timport glob\n29\timport os\n30\timport re\n31\timport sys\n32\t\n33\tMERMAID_BLOCK = re.compile(r\"```mermaid\\b(.*?)```\", re.S)\n34\tEDGE_LINE = re.compile(r\"^\\s*([A-Za-z0-9_-]+)(?:\\[[^\\]]*\\]|\\(\\w+\\)|\\{[^}]*\\})?\\s*\"\n35\t                       r\"(-->|-\\.->|==>)\\s*\"\n36\t                       r\"([A-Za-z0-9_-]+)\", re.M)\n37\tBRANCH_INFIX = re.compile(r\"-BRANCH-[A-Z]-\")\n38\tEPIC_FILE = re.compile(r\"^(?P<id>.+?-E\\d{3})\\.md$\")\n39\t\n40\t\n41\tdef parse_frontmatter(text):\n42\t    \"\"\"Return (dict, body). Values are raw strings; lists stay raw text.\"\"\"\n43\t    if not text.startswith(\"---\"):\n44\t        return {}, text\n45\t    parts = text.split(\"---\", 2)\n46\t    if len(parts) < 3:\n47\t        return {}, text\n48\t    fm = {}\n49\t    current_key = None\n50\t    for line in parts[1].splitlines():\n51\t        if not line.strip() or line.strip().startswith(\"#\"):\n52\t            current_key = None\n53\t            continue\n54\t        m = re.match(r\"^([A-Za-z0-9_.]+):\\s*(.*)$\", line)\n55\t        if m and not line.startswith(\" \"):\n56\t            fm[m.group(1)] = m.group(2).strip()\n57\t            current_key = m.group(1)\n58\t        elif line.strip().startswith(\"- \") and current_key:\n59\t            fm[current_key] = (fm.get(current_key, \"\") + \"\\n\" + line.strip()[2:]).strip()\n60\t    return fm, parts[2]\n61\t\n62\t\n63\tdef parse_dependencies(raw):\n64\t    \"\"\"Parse a frontmatter dependencies value: inline list, block list,\n65\t    comma-separated string, or quoted string. Returns list of ids.\"\"\"\n66\t    if raw is None:\n67\t        return []\n68\t    ids = []\n69\t    for piece in re.split(r\"[,\\n]+\", raw):\n70\t        piece = piece.strip()\n71\t        if piece.startswith(\"- \"):\n72\t            piece = piece[2:]\n73\t        piece = piece.strip(\"\\\"'[]{} \")\n74\t        if piece:\n75\t            ids.append(piece)\n76\t    return ids\n77\t\n78\t\n79\tdef mermaid_edges(summary_text):\n80\t    \"\"\"Return the set of (dependency, dependent) short-id edges from all\n81\t    mermaid blocks. Node tokens may be short (E001) or full ids.\"\"\"\n82\t    edges = set()\n83\t    for block in MERMAID_BLOCK.findall(summary_text):\n84\t        for line in block.splitlines():\n85\t            line = line.strip()\n86\t            if not line or line.startswith((\"classDef\", \"style\", \"subgraph\",\n87\t                                            \"end\", \"click\", \"%%\")):\n88\t                continue\n89\t            for m in EDGE_LINE.finditer(line):\n90\t                edges.add((m.group(1), m.group(3)))\n91\t    return edges\n92\t\n93\t\n94\tdef normalize(node, strat_id):\n95\t    \"\"\"Map a mermaid node token to a full epic id when possible.\"\"\"\n96\t    if node.startswith(strat_id + \"-\"):\n97\t        return node\n98\t    if re.fullmatch(r\"E\\d{3}\", node):\n99\t        return f\"{strat_id}-{node}\"\n100\t    return node\n101\t\n102\t\n103\tdef load_epics(epic_dir, strat_id):\n104\t    \"\"\"Return (main_plan, branch): dicts epic_id -> {'file', 'deps'}.\"\"\"\n105\t    main_plan, branch = {}, {}\n106\t    pattern = os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9].md\")\n107\t    for path in sorted(glob.glob(pattern)):\n108\t        name = os.path.basename(path)\n109\t        if name.endswith(\"-ai-signals.md\"):\n110\t            continue\n111\t        m = EPIC_FILE.match(name)\n112\t        if not m:\n113\t            continue\n114\t        epic_id = m.group(\"id\")\n115\t        fm, _ = parse_frontmatter(open(path, encoding=\"utf-8\", errors=\"replace\").read())\n116\t        entry = {\"file\": name, \"deps\": parse_dependencies(fm.get(\"dependencies\"))}\n117\t        if BRANCH_INFIX.search(epic_id):\n118\t            branch[epic_id] = entry\n119\t        else:\n120\t            main_plan[epic_id] = entry\n121\t    return main_plan, branch\n122\t\n123\t\n124\tdef check(strat_id, epic_dir):\n125\t    \"\"\"Return a list of finding strings.\"\"\"\n126\t    findings = []\n127\t    summary_path = os.path.join(epic_dir, f\"{strat_id}-decomposition.md\")\n128\t    if not os.path.isdir(epic_dir) or not os.path.exists(summary_path):\n129\t        return None  # nothing to check yet (triaged/incomplete) — not an error\n130\t    summary_text = open(summary_path, encoding=\"utf-8\", errors=\"replace\").read()\n131\t    main_plan, branch = load_epics(epic_dir, strat_id)\n132\t    all_ids = set(main_plan) | set(branch)\n133\t\n134\t    # dangling dependencies + main-plan->branch deps\n135\t    for epic_id, entry in sorted(list(main_plan.items()) + list(branch.items())):\n136\t        for dep in entry[\"deps\"]:\n137\t            if dep.endswith(\"-ai-signals\"):\n138\t                continue\n139\t            if BRANCH_INFIX.search(dep) and epic_id in main_plan:\n140\t                findings.append(\n141\t                    f\"FINDING main-plan-branch-dep: {entry['file']} lists branch epic \"\n142\t                    f\"{dep} in dependencies — branch epics are never created as issues. \"\n143\t                    f\"Fix: depend on the gating Investigation epic instead, or move this \"\n144\t                    f\"work into that branch.\")\n145\t            elif dep not in all_ids:\n146\t                findings.append(\n147\t                    f\"FINDING dangling-dependency: {entry['file']} depends on {dep}, \"\n148\t                    f\"which has no epic file. Fix: remove the dependency or create the \"\n149\t                    f\"epic file.\")\n150\t\n151\t    # mermaid <-> frontmatter (main-plan only; branch conventions differ)\n152\t    has_mermaid = bool(MERMAID_BLOCK.search(summary_text))\n153\t    if has_mermaid and main_plan:\n154\t        diagram = {(normalize(a, strat_id), normalize(b, strat_id))\n155\t                   for a, b in mermaid_edges(summary_text)}\n156\t        fm_edges = set()\n157\t        for epic_id, entry in main_plan.items():\n158\t            for dep in entry[\"deps\"]:\n159\t                fm_edges.add((dep, epic_id))\n160\t        # restrict comparison to edges between main-plan epics\n161\t        diag_main = {(a, b) for a, b in diagram\n162\t                     if a in main_plan and b in main_plan}\n163\t        for dep, epic_id in sorted(fm_edges - diag_main):\n164\t            findings.append(\n165\t                f\"FINDING mermaid-frontmatter: {main_plan[epic_id]['file']} declares a \"\n166\t                f\"dependency on {dep}, but the summary's Mermaid DAG has no \"\n167\t                f\"{dep.split('-')[-1]} --> {epic_id.split('-')[-1]} arrow. \"\n168\t                f\"Fix: add the arrow to the Mermaid diagram.\")\n169\t        for dep, epic_id in sorted(diag_main - fm_edges):\n170\t            findings.append(\n171\t                f\"FINDING mermaid-frontmatter: the summary's Mermaid DAG draws \"\n172\t                f\"{dep.split('-')[-1]} --> {epic_id.split('-')[-1]}, but \"\n173\t                f\"{main_plan[epic_id]['file']} does not list {dep} in its frontmatter \"\n174\t                f\"dependencies. Fix: add {dep} to that epic's dependencies (or remove \"\n175\t                f\"the arrow if it is not a real dependency).\")\n176\t\n177\t    # cycles over all epics\n178\t    graph = {eid: [d for d in e[\"deps\"] if d in all_ids]\n179\t             for eid, e in list(main_plan.items()) + list(branch.items())}\n180\t    WHITE, GRAY, BLACK = 0, 1, 2\n181\t    color = {eid: WHITE for eid in graph}\n182\t\n183\t    def visit(node, stack):\n184\t        color[node] = GRAY\n185\t        for nxt in graph.get(node, []):\n186\t            if color.get(nxt) == GRAY:\n187\t                findings.append(\n188\t                    f\"FINDING dependency-cycle: \"\n189\t                    f\"{' -> '.join(stack + [node, nxt])}. \"\n190\t                    f\"Fix: remove the least-justified edge in the cycle.\")\n191\t            elif color.get(nxt) == WHITE:\n192\t                visit(nxt, stack + [node])\n193\t        color[node] = BLACK\n194\t\n195\t    for eid in sorted(graph):\n196\t        if color[eid] == WHITE:\n197\t            visit(eid, [])\n198\t    return findings\n199\t\n200\t\n201\tdef run(strat_id, epic_dir):\n202\t    try:\n203\t        findings = check(strat_id, epic_dir)\n204\t    except Exception as exc:  # fail-open: never block the pipeline\n205\t        print(f\"consistency check unavailable: {exc}\")\n206\t        return 0\n207\t    if findings is None:\n208\t        print(\"OK: no decomposition artifacts to check yet\")\n209\t        return 0\n210\t    if not findings:\n211\t        n = len(glob.glob(os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9].md\"))) \\\n212\t            - len(glob.glob(os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9]-ai-signals.md\")))\n213\t        print(f\"OK: no structural findings ({n} epics checked)\")\n214\t        return 0\n215\t    for f in findings:\n216\t        print(f)\n217\t    return 1\n218\t\n219\t\n220\tdef self_check():\n221\t    import tempfile\n222\t    ok = [0]\n223\t\n224\t    def case(name, files, expect_findings):\n225\t        with tempfile.TemporaryDirectory() as td:\n226\t            ed = os.path.join(td, \"artifacts\", \"epic-tasks\")\n227\t            os.makedirs(ed)\n228\t            for fname, content in files.items():\n229\t                open(os.path.join(ed, fname), \"w\").write(content)\n230\t            got = check(\"STRAT-1\", ed) or []\n231\t            matched = (len(got) > 0) == expect_findings\n232\t            ok[0] += matched\n233\t            print(f\"  {'PASS' if matched else 'FAIL'} {name}: {len(got)} finding(s)\"\n234\t                  f\"{'' if matched else ' (expected findings=' + str(expect_findings) + ')'}\")\n235\t\n236\t    def epic(eid, deps):\n237\t        if deps:\n238\t            depstr = \"dependencies:\\n\" + \"\\n\".join(f\"- {d}\" for d in deps)\n239\t        else:\n240\t            depstr = \"dependencies: []\"\n241\t        return f\"---\\nepic_id: {eid}\\n{depstr}\\n---\\n# {eid}\\n\"\n242\t\n243\t    summary_dag = (\"---\\nparent_strat: STRAT-1\\n---\\n# S\\n```mermaid\\ngraph TD\\n\"\n244\t                   \"E001[\\\"a\\\"] --> E002[\\\"b\\\"]\\nE002 --> E003[\\\"c\\\"]\\n```\\n\")\n245\t    case(\"consistent dag\", {\n246\t        \"STRAT-1-decomposition.md\": summary_dag,\n247\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n248\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n249\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E002\"]),\n250\t    }, False)\n251\t    case(\"frontmatter dep missing from diagram\", {\n252\t        \"STRAT-1-decomposition.md\": summary_dag,\n253\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n254\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n255\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E001\", \"STRAT-1-E002\"]),\n256\t    }, True)\n257\t    case(\"diagram edge missing from frontmatter\", {\n258\t        \"STRAT-1-decomposition.md\": (\"---\\n---\\n```mermaid\\ngraph TD\\n\"\n259\t                                     \"E001 --> E002\\nE002 --> E003\\nE001 --> E003\\n```\\n\"),\n260\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n261\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n262\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E002\"]),\n263\t    }, True)\n264\t    case(\"dangling dependency\", {\n265\t        \"STRAT-1-decomposition.md\": summary_dag,\n266\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n267\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n268\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E009\"]),\n269\t    }, True)\n270\t    case(\"dependency cycle\", {\n271\t        \"STRAT-1-decomposition.md\": (\"---\\n---\\n```mermaid\\ngraph TD\\n\"\n272\t                                     \"E001 --> E002\\nE002 --> E001\\n```\\n\"),\n273\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", [\"STRAT-1-E002\"]),\n274\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n275\t    }, True)\n276\t    case(\"branch epics excluded from diagram comparison\", {\n277\t        \"STRAT-1-decomposition.md\": summary_dag,\n278\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n279\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n280\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E002\"]),\n281\t        \"STRAT-1-BRANCH-A-E004.md\": epic(\"STRAT-1-BRANCH-A-E004\",\n282\t                                         [\"STRAT-1-E003\"]),\n283\t        \"STRAT-1-BRANCH-A-E005.md\": epic(\"STRAT-1-BRANCH-A-E005\",\n284\t                                         [\"STRAT-1-BRANCH-A-E004\"]),\n285\t    }, False)\n286\t    case(\"main-plan epic depending on branch epic\", {\n287\t        \"STRAT-1-decomposition.md\": summary_dag,\n288\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n289\t        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n290\t        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-BRANCH-A-E004\"]),\n291\t        \"STRAT-1-BRANCH-A-E004.md\": epic(\"STRAT-1-BRANCH-A-E004\", []),\n292\t    }, True)\n293\t    case(\"no mermaid (triaged single epic) is not a finding\", {\n294\t        \"STRAT-1-decomposition.md\": \"---\\ntriage: below-threshold\\n---\\n# S\\n\",\n295\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n296\t    }, False)\n297\t    case(\"comma-string dependencies parse\", {\n298\t        \"STRAT-1-decomposition.md\": summary_dag,\n299\t        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n300\t        \"STRAT-1-E002.md\": (\"---\\nepic_id: STRAT-1-E002\\n\"\n301\t                            \"dependencies: \\\"STRAT-1-E001\\\"\\n---\\n\"),\n302\t        \"STRAT-1-E003.md\": (\"---\\nepic_id: STRAT-1-E003\\n\"\n303\t                            \"dependencies: [STRAT-1-E002]\\n---\\n\"),\n304\t    }, False)\n305\t    print(f\"self-check: {ok[0]}/9 cases pass\")\n306\t    return 0 if ok[0] == 9 else 1\n307\t\n308\t\n309\tdef main(argv):\n310\t    if \"--self-check\" in argv:\n311\t        return self_check()\n312\t    args = [a for a in argv[1:] if not a.startswith(\"--\")]\n313\t    epic_dir = \"artifacts/epic-tasks\"\n314\t    for i, a in enumerate(argv):\n315\t        if a == \"--epic-dir\" and i + 1 < len(argv):\n316\t            epic_dir = argv[i + 1]\n317\t    if len(args) < 1:\n318\t        print(__doc__)\n319\t        return 2\n320\t    return run(args[0], epic_dir)\n321\t\n322\t\n323\tif __name__ == \"__main__\":\n324\t    sys.exit(main(sys.argv))\n325\t"}]},"parent_tool_use_id":null,"session_id":"7da9b899-2570-4f45-9105-189f12061fa7","uuid":"56a1dfe9-f246-43fd-afa5-c0d54bc33532","timestamp":"2026-10-09T12:26:06.298Z","tool_use_result":{"type":"text","file":{"filePath":"/private/var/folders/h5/l8qslbp55w5621qf9ngsh5jc0000gn/T/epic_case-016-component-canonicalization_0_0uz2244h/skills/epic-decompose/epic-decompose/scripts/check_decomposition.py","content":"#!/usr/bin/env python3\n\"\"\"Structural consistency self-check for epic decompositions.\n\nUsage:\n    python3 check_decomposition.py <STRATEGY_ID> [--epic-dir artifacts/epic-tasks]\n    python3 check_decomposition.py --self-check\n\nChecks (structural invariants only — no semantic judgment, so a finding is\nalways a real inconsistency the downstream review rubric scores as critical):\n\n  mermaid-frontmatter   Every dependency edge in the decomposition summary's\n                        Mermaid DAG has a matching entry in the dependent\n                        epic's frontmatter `dependencies`, and every\n                        frontmatter dependency of a main-plan epic appears as\n                        an edge in the diagram (both directions).\n  dangling-dependency   An epic's `dependencies` references an epic_id that\n                        has no file on disk.\n  main-plan-branch-dep  A main-plan epic lists a `-BRANCH-<letter>-` epic in\n                        its `dependencies` (branch epics are never created as\n                        issues; depending on one dangles).\n  dependency-cycle      The frontmatter dependency graph has a cycle.\n\nEach finding names the file, the defect, and the exact fix. Exit 0 with\n\"OK: ...\" when there are no findings; exit 1 with FINDING lines otherwise.\nExit 2 on usage/parse trouble BEFORE any artifacts were read (callers treat\nnon-zero-with-no-FINDING-lines as \"check unavailable\" and proceed).\n\"\"\"\nimport glob\nimport os\nimport re\nimport sys\n\nMERMAID_BLOCK = re.compile(r\"```mermaid\\b(.*?)```\", re.S)\nEDGE_LINE = re.compile(r\"^\\s*([A-Za-z0-9_-]+)(?:\\[[^\\]]*\\]|\\(\\w+\\)|\\{[^}]*\\})?\\s*\"\n                       r\"(-->|-\\.->|==>)\\s*\"\n                       r\"([A-Za-z0-9_-]+)\", re.M)\nBRANCH_INFIX = re.compile(r\"-BRANCH-[A-Z]-\")\nEPIC_FILE = re.compile(r\"^(?P<id>.+?-E\\d{3})\\.md$\")\n\n\ndef parse_frontmatter(text):\n    \"\"\"Return (dict, body). Values are raw strings; lists stay raw text.\"\"\"\n    if not text.startswith(\"---\"):\n        return {}, text\n    parts = text.split(\"---\", 2)\n    if len(parts) < 3:\n        return {}, text\n    fm = {}\n    current_key = None\n    for line in parts[1].splitlines():\n        if not line.strip() or line.strip().startswith(\"#\"):\n            current_key = None\n            continue\n        m = re.match(r\"^([A-Za-z0-9_.]+):\\s*(.*)$\", line)\n        if m and not line.startswith(\" \"):\n            fm[m.group(1)] = m.group(2).strip()\n            current_key = m.group(1)\n        elif line.strip().startswith(\"- \") and current_key:\n            fm[current_key] = (fm.get(current_key, \"\") + \"\\n\" + line.strip()[2:]).strip()\n    return fm, parts[2]\n\n\ndef parse_dependencies(raw):\n    \"\"\"Parse a frontmatter dependencies value: inline list, block list,\n    comma-separated string, or quoted string. Returns list of ids.\"\"\"\n    if raw is None:\n        return []\n    ids = []\n    for piece in re.split(r\"[,\\n]+\", raw):\n        piece = piece.strip()\n        if piece.startswith(\"- \"):\n            piece = piece[2:]\n        piece = piece.strip(\"\\\"'[]{} \")\n        if piece:\n            ids.append(piece)\n    return ids\n\n\ndef mermaid_edges(summary_text):\n    \"\"\"Return the set of (dependency, dependent) short-id edges from all\n    mermaid blocks. Node tokens may be short (E001) or full ids.\"\"\"\n    edges = set()\n    for block in MERMAID_BLOCK.findall(summary_text):\n        for line in block.splitlines():\n            line = line.strip()\n            if not line or line.startswith((\"classDef\", \"style\", \"subgraph\",\n                                            \"end\", \"click\", \"%%\")):\n                continue\n            for m in EDGE_LINE.finditer(line):\n                edges.add((m.group(1), m.group(3)))\n    return edges\n\n\ndef normalize(node, strat_id):\n    \"\"\"Map a mermaid node token to a full epic id when possible.\"\"\"\n    if node.startswith(strat_id + \"-\"):\n        return node\n    if re.fullmatch(r\"E\\d{3}\", node):\n        return f\"{strat_id}-{node}\"\n    return node\n\n\ndef load_epics(epic_dir, strat_id):\n    \"\"\"Return (main_plan, branch): dicts epic_id -> {'file', 'deps'}.\"\"\"\n    main_plan, branch = {}, {}\n    pattern = os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9].md\")\n    for path in sorted(glob.glob(pattern)):\n        name = os.path.basename(path)\n        if name.endswith(\"-ai-signals.md\"):\n            continue\n        m = EPIC_FILE.match(name)\n        if not m:\n            continue\n        epic_id = m.group(\"id\")\n        fm, _ = parse_frontmatter(open(path, encoding=\"utf-8\", errors=\"replace\").read())\n        entry = {\"file\": name, \"deps\": parse_dependencies(fm.get(\"dependencies\"))}\n        if BRANCH_INFIX.search(epic_id):\n            branch[epic_id] = entry\n        else:\n            main_plan[epic_id] = entry\n    return main_plan, branch\n\n\ndef check(strat_id, epic_dir):\n    \"\"\"Return a list of finding strings.\"\"\"\n    findings = []\n    summary_path = os.path.join(epic_dir, f\"{strat_id}-decomposition.md\")\n    if not os.path.isdir(epic_dir) or not os.path.exists(summary_path):\n        return None  # nothing to check yet (triaged/incomplete) — not an error\n    summary_text = open(summary_path, encoding=\"utf-8\", errors=\"replace\").read()\n    main_plan, branch = load_epics(epic_dir, strat_id)\n    all_ids = set(main_plan) | set(branch)\n\n    # dangling dependencies + main-plan->branch deps\n    for epic_id, entry in sorted(list(main_plan.items()) + list(branch.items())):\n        for dep in entry[\"deps\"]:\n            if dep.endswith(\"-ai-signals\"):\n                continue\n            if BRANCH_INFIX.search(dep) and epic_id in main_plan:\n                findings.append(\n                    f\"FINDING main-plan-branch-dep: {entry['file']} lists branch epic \"\n                    f\"{dep} in dependencies — branch epics are never created as issues. \"\n                    f\"Fix: depend on the gating Investigation epic instead, or move this \"\n                    f\"work into that branch.\")\n            elif dep not in all_ids:\n                findings.append(\n                    f\"FINDING dangling-dependency: {entry['file']} depends on {dep}, \"\n                    f\"which has no epic file. Fix: remove the dependency or create the \"\n                    f\"epic file.\")\n\n    # mermaid <-> frontmatter (main-plan only; branch conventions differ)\n    has_mermaid = bool(MERMAID_BLOCK.search(summary_text))\n    if has_mermaid and main_plan:\n        diagram = {(normalize(a, strat_id), normalize(b, strat_id))\n                   for a, b in mermaid_edges(summary_text)}\n        fm_edges = set()\n        for epic_id, entry in main_plan.items():\n            for dep in entry[\"deps\"]:\n                fm_edges.add((dep, epic_id))\n        # restrict comparison to edges between main-plan epics\n        diag_main = {(a, b) for a, b in diagram\n                     if a in main_plan and b in main_plan}\n        for dep, epic_id in sorted(fm_edges - diag_main):\n            findings.append(\n                f\"FINDING mermaid-frontmatter: {main_plan[epic_id]['file']} declares a \"\n                f\"dependency on {dep}, but the summary's Mermaid DAG has no \"\n                f\"{dep.split('-')[-1]} --> {epic_id.split('-')[-1]} arrow. \"\n                f\"Fix: add the arrow to the Mermaid diagram.\")\n        for dep, epic_id in sorted(diag_main - fm_edges):\n            findings.append(\n                f\"FINDING mermaid-frontmatter: the summary's Mermaid DAG draws \"\n                f\"{dep.split('-')[-1]} --> {epic_id.split('-')[-1]}, but \"\n                f\"{main_plan[epic_id]['file']} does not list {dep} in its frontmatter \"\n                f\"dependencies. Fix: add {dep} to that epic's dependencies (or remove \"\n                f\"the arrow if it is not a real dependency).\")\n\n    # cycles over all epics\n    graph = {eid: [d for d in e[\"deps\"] if d in all_ids]\n             for eid, e in list(main_plan.items()) + list(branch.items())}\n    WHITE, GRAY, BLACK = 0, 1, 2\n    color = {eid: WHITE for eid in graph}\n\n    def visit(node, stack):\n        color[node] = GRAY\n        for nxt in graph.get(node, []):\n            if color.get(nxt) == GRAY:\n                findings.append(\n                    f\"FINDING dependency-cycle: \"\n                    f\"{' -> '.join(stack + [node, nxt])}. \"\n                    f\"Fix: remove the least-justified edge in the cycle.\")\n            elif color.get(nxt) == WHITE:\n                visit(nxt, stack + [node])\n        color[node] = BLACK\n\n    for eid in sorted(graph):\n        if color[eid] == WHITE:\n            visit(eid, [])\n    return findings\n\n\ndef run(strat_id, epic_dir):\n    try:\n        findings = check(strat_id, epic_dir)\n    except Exception as exc:  # fail-open: never block the pipeline\n        print(f\"consistency check unavailable: {exc}\")\n        return 0\n    if findings is None:\n        print(\"OK: no decomposition artifacts to check yet\")\n        return 0\n    if not findings:\n        n = len(glob.glob(os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9].md\"))) \\\n            - len(glob.glob(os.path.join(epic_dir, f\"{strat_id}-*E[0-9][0-9][0-9]-ai-signals.md\")))\n        print(f\"OK: no structural findings ({n} epics checked)\")\n        return 0\n    for f in findings:\n        print(f)\n    return 1\n\n\ndef self_check():\n    import tempfile\n    ok = [0]\n\n    def case(name, files, expect_findings):\n        with tempfile.TemporaryDirectory() as td:\n            ed = os.path.join(td, \"artifacts\", \"epic-tasks\")\n            os.makedirs(ed)\n            for fname, content in files.items():\n                open(os.path.join(ed, fname), \"w\").write(content)\n            got = check(\"STRAT-1\", ed) or []\n            matched = (len(got) > 0) == expect_findings\n            ok[0] += matched\n            print(f\"  {'PASS' if matched else 'FAIL'} {name}: {len(got)} finding(s)\"\n                  f\"{'' if matched else ' (expected findings=' + str(expect_findings) + ')'}\")\n\n    def epic(eid, deps):\n        if deps:\n            depstr = \"dependencies:\\n\" + \"\\n\".join(f\"- {d}\" for d in deps)\n        else:\n            depstr = \"dependencies: []\"\n        return f\"---\\nepic_id: {eid}\\n{depstr}\\n---\\n# {eid}\\n\"\n\n    summary_dag = (\"---\\nparent_strat: STRAT-1\\n---\\n# S\\n```mermaid\\ngraph TD\\n\"\n                   \"E001[\\\"a\\\"] --> E002[\\\"b\\\"]\\nE002 --> E003[\\\"c\\\"]\\n```\\n\")\n    case(\"consistent dag\", {\n        \"STRAT-1-decomposition.md\": summary_dag,\n        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n        \"STRAT-1-E002.md\": epic(\"STRAT-1-E002\", [\"STRAT-1-E001\"]),\n        \"STRAT-1-E003.md\": epic(\"STRAT-1-E003\", [\"STRAT-1-E002\"]),\n    }, False)\n    case(\"frontmatter dep missing from diagram\", {\n        \"STRAT-1-decomposition.md\": summary_dag,\n        \"STRAT-1-E001.md\": epic(\"STRAT-1-E001\", []),\n       